class Solution {
    int covered(vector<vector<int>>& darts,double x,double y,int r){
        int answer=0;
        for(auto& point:darts){
            double dx=point[0]-x,dy=point[1]-y;
            answer+=dx*dx+dy*dy<=r*(double)r+1e-7;
        }
        return answer;
    }
    public:int numPoints(vector<vector<int>>& darts,int r){
        int answer=1;
        for(int i=0;i<(int)darts.size();++i)for(int j=i+1;j<(int)darts.size();++j){
            double dx=darts[j][0]-darts[i][0],dy=darts[j][1]-darts[i][1],distance=hypot(dx,dy);
            if(distance==0||distance>2.0*r+1e-9)continue;
            double middleX=(darts[i][0]+darts[j][0])/2.0,middleY=(darts[i][1]+darts[j][1])/2.0,height=sqrt(max(0.0,r*(double)r-distance*distance/4));
            double offsetX=-dy/distance*height,offsetY=dx/distance*height;
            answer=max({
                answer,covered(darts,middleX+offsetX,middleY+offsetY,r),covered(darts,middleX-offsetX,middleY-offsetY,r)
            });
        }
        return answer;
    }
};
